"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[64426],{64426:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/after-school.png\\"\\n          title=\\"방과 후\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"창해\\"\\n          publishedDate=\\"2007-07-25\\"\\n          isbn=\\"9788979197686\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n```히가시노 게이고```의 데뷔작이라고 할 수 있다.  \\n이후 그의 모든 작품 스타일이 형성된 중요한 작품인 듯하다.  \\n<br>\\n<mark>밀실 살인</mark>이라는 지극히 고전적인 퍼즐과 지극히 논리적이고 기계적인 해답을 제시한다.  \\n이러한 물리 법칙과 도구의 활용에 기반한 공학적 해결은 작가가 엔지니어 출신이라는 점의 영향이지 않을까 생각된다.  \\n<br>\\n작가는 의도적으로 성인의 상식으로는 납득하기 어려운 동기를 제시하여, 여고생이라는 폐쇄된 사회의 특수한 심리 상태를 극적으로 나타낸 듯하다.  \\n```순수성```의 훼손은 존재 자체를 위협하는 공포이며, 법을 초월하는 행동 원리가 된다.  \\n<br>\\n<mark>이해할 수 없는 동기</mark>야 말로 세대 간에 메울 수 없는 심리적 간극과 소통의 단절이지 않을까?\\n<br>\\n엉뚱한 미스터리를 해결하는 데 성공하는 바로 그 순간 파멸을 맞는 설정은 지적 능력만으로는 인간관계의 파국을 막을 수 없다는 메시지로 보인다."}')}}]);